'use strict';
// Multiconnect, single-file build. Made by build-single.js. Run with: node server.js
const EMBEDDED = {"/apple-touch-icon.png":"","/icon-192.png":"","/icon-512.png":"","/icon-maskable-512.png":"","/index.html":"","/manifest.webmanifest":"","/room.html":"","/room.js":"","/style.css":"","/sw.js":""};
/*
 * Multiconnect server. No packages to install: Node 18 or newer is enough.
 *   node server.js
 * Settings (environment variables): PORT (default 3000), MAX_MB (default 300).
 */
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const os = require('os');

const PORT = Number(process.env.PORT) || 3000;
const MAX_BYTES = (Number(process.env.MAX_MB) || 300) * 1024 * 1024;
const PUBLIC = path.join(__dirname, 'public');
const UPLOADS = process.env.UPLOAD_DIR || path.join(__dirname, 'uploads');
const SESSION_TTL = 12 * 60 * 60 * 1000;
const MAX_SESSIONS = 500;
const CODE_CHARS = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const WS_GUID = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11';

fs.rmSync(UPLOADS, { recursive: true, force: true });
fs.mkdirSync(UPLOADS, { recursive: true });

const MIME = {
  '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8', '.svg': 'image/svg+xml', '.json': 'application/json', '.webmanifest': 'application/manifest+json',
  '.png': 'image/png', '.ico': 'image/x-icon', '.pdf': 'application/pdf',
  '.webmanifest': 'application/manifest+json', '.mp4': 'video/mp4', '.webm': 'video/webm', '.woff2': 'font/woff2',
};
const FILE_TYPES = { pdf: ['.pdf'], video: ['.mp4', '.webm'] };

/** code -> { code, hostToken, file, pos, playing, time, stamp, clients:Set, touched } */
const sessions = new Map();
const createLog = new Map(); // ip -> [timestamps]

/* ---------- helpers ---------- */
function json(res, status, body) {
  const s = JSON.stringify(body);
  res.writeHead(status, { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' });
  res.end(s);
}
function newCode() {
  for (let n = 0; n < 50; n++) {
    let c = '';
    const b = crypto.randomBytes(6);
    for (let i = 0; i < 6; i++) c += CODE_CHARS[b[i] % CODE_CHARS.length];
    if (!sessions.has(c)) return c;
  }
  return null;
}
function getSession(code) {
  const s = sessions.get(String(code || '').toUpperCase());
  if (s) s.touched = Date.now();
  return s;
}
function isHostToken(s, token) {
  if (!s || typeof token !== 'string' || token.length !== s.hostToken.length) return false;
  return crypto.timingSafeEqual(Buffer.from(token), Buffer.from(s.hostToken));
}
function lanAddresses() {
  const out = [];
  const nets = os.networkInterfaces();
  for (const name of Object.keys(nets)) {
    for (const n of nets[name] || []) {
      if (n.family === 'IPv4' && !n.internal) out.push('http://' + n.address + ':' + PORT);
    }
  }
  return out;
}
function currentPos(s) {
  if (s.file && s.file.kind === 'video' && s.playing) return s.time + (Date.now() - s.stamp) / 1000;
  return s.time;
}
function publicFile(f) {
  return f ? { id: f.id, kind: f.kind, name: f.name, size: f.size } : null;
}
function removeFile(s) {
  if (s.file) fs.rm(s.file.path, { force: true }, () => {});
  s.file = null;
}

/* ---------- websocket (RFC 6455, text frames only) ---------- */
function wsSend(sock, text) {
  if (sock.destroyed || !sock.writable) return;
  const payload = Buffer.from(text);
  let head;
  if (payload.length < 126) head = Buffer.from([0x81, payload.length]);
  else if (payload.length < 65536) { head = Buffer.alloc(4); head[0] = 0x81; head[1] = 126; head.writeUInt16BE(payload.length, 2); }
  else { head = Buffer.alloc(10); head[0] = 0x81; head[1] = 127; head.writeBigUInt64BE(BigInt(payload.length), 2); }
  sock.write(Buffer.concat([head, payload]));
}
function broadcast(s, obj, opts) {
  const text = JSON.stringify(obj);
  const lossy = opts && opts.lossy;
  for (const c of s.clients) {
    if (opts && opts.skipHosts && c.isHost) continue;
    if (lossy && c.sock.writableLength > 256 * 1024) continue; // slow phone: skip, next update catches up
    wsSend(c.sock, text);
  }
}
const viewerTimers = new Map();
function scheduleViewers(s) {
  if (viewerTimers.has(s.code)) return;
  viewerTimers.set(s.code, setTimeout(() => {
    viewerTimers.delete(s.code);
    let n = 0;
    for (const c of s.clients) if (!c.isHost) n++;
    broadcast(s, { t: 'viewers', n });
  }, 800));
}

function handleUpgrade(req, sock) {
  const url = new URL(req.url, 'http://x');
  const key = req.headers['sec-websocket-key'];
  if (url.pathname !== '/ws' || !key) { sock.destroy(); return; }
  const s = getSession(url.searchParams.get('code'));
  if (!s) { sock.write('HTTP/1.1 404 Not Found\r\nConnection: close\r\n\r\n'); sock.destroy(); return; }
  const accept = crypto.createHash('sha1').update(key + WS_GUID).digest('base64');
  sock.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ' + accept + '\r\n\r\n');
  sock.setNoDelay(true);
  sock.setKeepAlive(true, 30000);

  const client = { sock, isHost: isHostToken(s, url.searchParams.get('token')) };
  s.clients.add(client);
  let nonHost = 0;
  for (const c of s.clients) if (!c.isHost) nonHost++;
  wsSend(sock, JSON.stringify({
    t: 'hello', role: client.isHost ? 'host' : 'student', file: publicFile(s.file),
    pos: s.file && s.file.kind === 'pdf' ? s.time : 0,
    playing: s.playing, time: currentPos(s), viewers: nonHost,
  }));
  scheduleViewers(s);

  let buf = Buffer.alloc(0);
  let frag = null;
  sock.on('data', (chunk) => {
    buf = Buffer.concat([buf, chunk]);
    for (;;) {
      if (buf.length < 2) return;
      const fin = (buf[0] & 0x80) !== 0;
      const op = buf[0] & 0x0f;
      const masked = (buf[1] & 0x80) !== 0;
      let len = buf[1] & 0x7f;
      let off = 2;
      if (len === 126) { if (buf.length < 4) return; len = buf.readUInt16BE(2); off = 4; }
      else if (len === 127) { if (buf.length < 10) return; len = Number(buf.readBigUInt64BE(2)); off = 10; }
      if (len > 65536 || !masked) { sock.destroy(); return; }
      if (buf.length < off + 4 + len) return;
      const mask = buf.subarray(off, off + 4);
      const data = Buffer.from(buf.subarray(off + 4, off + 4 + len));
      for (let i = 0; i < data.length; i++) data[i] ^= mask[i & 3];
      buf = buf.subarray(off + 4 + len);
      if (op === 8) { sock.end(); return; }
      if (op === 9) { sock.write(Buffer.concat([Buffer.from([0x8a, data.length]), data.subarray(0, 125)])); continue; }
      if (op === 1 || op === 0) {
        frag = op === 1 ? [data] : (frag || []).concat([data]);
        if (fin) { const text = Buffer.concat(frag).toString('utf8'); frag = null; onMessage(text); }
      }
    }
  });
  function onMessage(text) {
    if (!client.isHost) return;
    let m;
    try { m = JSON.parse(text); } catch (e) { return; }
    if (!m || !s.file) return;
    if (m.t === 'pos' && s.file.kind === 'pdf' && Number.isFinite(m.pos)) {
      s.time = Math.max(0, m.pos);
      broadcast(s, { t: 'pos', id: s.file.id, pos: s.time }, { skipHosts: true, lossy: true });
    } else if (m.t === 'vid' && s.file.kind === 'video' && Number.isFinite(m.time)) {
      s.time = Math.max(0, m.time);
      s.playing = !!m.playing;
      s.stamp = Date.now();
      broadcast(s, { t: 'vid', id: s.file.id, playing: s.playing, time: s.time, hb: m.hb === true }, { skipHosts: true });
    }
  }
  const done = () => { if (s.clients.delete(client)) scheduleViewers(s); };
  sock.on('close', done);
  sock.on('error', () => { done(); sock.destroy(); });
}

/* ---------- http ---------- */
function serveFile(req, res, filePath, mime, extraHeaders) {
  fs.stat(filePath, (err, st) => {
    if (err || !st.isFile()) { res.writeHead(404); res.end('Not found'); return; }
    const headers = Object.assign({ 'Content-Type': mime, 'Accept-Ranges': 'bytes' }, extraHeaders || {});
    let start = 0, end = st.size - 1, status = 200;
    const range = /^bytes=(\d*)-(\d*)$/.exec(req.headers.range || '');
    if (range && (range[1] || range[2])) {
      if (range[1]) { start = Number(range[1]); if (range[2]) end = Math.min(Number(range[2]), end); }
      else { start = Math.max(0, st.size - Number(range[2])); }
      if (start > end || start >= st.size) { res.writeHead(416, { 'Content-Range': 'bytes */' + st.size }); res.end(); return; }
      status = 206;
      headers['Content-Range'] = 'bytes ' + start + '-' + end + '/' + st.size;
    }
    headers['Content-Length'] = end - start + 1;
    res.writeHead(status, headers);
    if (req.method === 'HEAD') { res.end(); return; }
    const stream = fs.createReadStream(filePath, { start, end });
    stream.on('error', () => res.destroy());
    res.on('close', () => stream.destroy());
    stream.pipe(res);
  });
}

function handleUpload(req, res, s, url) {
  const name = String(url.searchParams.get('name') || 'file').replace(/[\\/\0-\x1f]/g, '_').slice(0, 150);
  const ext = path.extname(name).toLowerCase();
  const kind = FILE_TYPES.pdf.includes(ext) ? 'pdf' : FILE_TYPES.video.includes(ext) ? 'video' : null;
  if (!kind) return json(res, 400, { error: 'Choose a PDF, MP4 or WebM file.' });
  const declared = Number(req.headers['content-length']);
  if (!declared || declared > MAX_BYTES) {
    return json(res, 413, { error: 'That file is over ' + Math.round(MAX_BYTES / 1048576) + ' MB.' });
  }
  const id = crypto.randomBytes(8).toString('hex');
  const dest = path.join(UPLOADS, s.code + '-' + id + ext);
  const out = fs.createWriteStream(dest);
  let got = 0, failed = false;
  const fail = (status, msg) => {
    if (failed) return; failed = true;
    out.destroy(); fs.rm(dest, { force: true }, () => {});
    if (!res.headersSent) json(res, status, { error: msg });
    req.destroy();
  };
  req.on('data', (c) => { got += c.length; if (got > MAX_BYTES) fail(413, 'That file is too large.'); });
  req.on('error', () => fail(400, 'Upload interrupted.'));
  req.on('aborted', () => fail(400, 'Upload interrupted.'));
  req.pipe(out);
  out.on('error', () => fail(500, 'The server could not save the file.'));
  out.on('finish', () => {
    if (failed) return;
    removeFile(s);
    s.file = { id, kind, name, size: got, path: dest, ext };
    s.time = 0; s.playing = false; s.stamp = Date.now();
    broadcast(s, { t: 'file', file: publicFile(s.file), viewers: undefined });
    json(res, 200, { file: publicFile(s.file) });
  });
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://x');
  const p = url.pathname;
  res.setHeader('X-Content-Type-Options', 'nosniff');

  if (req.method === 'POST' && p === '/api/session') {
    const ip = String(req.headers['x-forwarded-for'] || '').split(',')[0].trim() || req.socket.remoteAddress || '';
    const now = Date.now();
    const recent = (createLog.get(ip) || []).filter((t) => now - t < 3600000);
    if (recent.length >= 30) return json(res, 429, { error: 'Too many classes started. Try again later.' });
    if (sessions.size >= MAX_SESSIONS) return json(res, 503, { error: 'The server is full. Try again later.' });
    const code = newCode();
    if (!code) return json(res, 503, { error: 'Could not create a class. Try again.' });
    recent.push(now); createLog.set(ip, recent);
    const hostToken = crypto.randomBytes(18).toString('base64url');
    sessions.set(code, { code, hostToken, file: null, time: 0, playing: false, stamp: now, clients: new Set(), touched: now });
    return json(res, 200, { code, hostToken });
  }

  if (req.method === 'GET' && p === '/api/info') {
    return json(res, 200, { lan: lanAddresses(), maxMb: Math.round(MAX_BYTES / 1048576) });
  }

  let m = /^\/api\/session\/([A-Za-z0-9]{6})$/.exec(p);
  if (m && req.method === 'GET') {
    const s = getSession(m[1]);
    return s ? json(res, 200, { exists: true, file: publicFile(s.file) }) : json(res, 404, { exists: false });
  }

  m = /^\/api\/session\/([A-Za-z0-9]{6})\/file$/.exec(p);
  if (m && (req.method === 'POST' || req.method === 'DELETE')) {
    const s = getSession(m[1]);
    if (!s) return json(res, 404, { error: 'That class has ended.' });
    if (!isHostToken(s, req.headers['x-host-token'])) return json(res, 403, { error: 'Only the host can change the file.' });
    if (req.method === 'DELETE') {
      removeFile(s);
      broadcast(s, { t: 'file', file: null });
      return json(res, 200, { ok: true });
    }
    return handleUpload(req, res, s, url);
  }

  m = /^\/files\/([A-Za-z0-9]{6})\/([a-f0-9]{16})$/.exec(p);
  if (m && (req.method === 'GET' || req.method === 'HEAD')) {
    const s = getSession(m[1]);
    if (!s || !s.file || s.file.id !== m[2]) { res.writeHead(404); return res.end('Not found'); }
    const headers = { 'Cache-Control': 'private, max-age=3600' };
    if (url.searchParams.get('dl')) {
      const plain = s.file.name.replace(/[^\x20-\x7e]/g, '_').replace(/["\\]/g, '_');
      headers['Content-Disposition'] = 'attachment; filename="' + plain + '"; filename*=UTF-8\'\'' + encodeURIComponent(s.file.name);
    }
    return serveFile(req, res, s.file.path, MIME[s.file.ext], headers);
  }

  if (req.method !== 'GET' && req.method !== 'HEAD') { res.writeHead(405); return res.end(); }

  // pages
  let rel = p;
  if (p === '/') rel = '/index.html';
  else if (/^\/c\/[A-Za-z0-9]{6}\/?$/.test(p)) rel = '/room.html';
  if (typeof EMBEDDED !== 'undefined') {   // single-file build: the website is inside this file
    const b64 = Object.prototype.hasOwnProperty.call(EMBEDDED, rel) ? EMBEDDED[rel] : null;
    if (!b64) { res.writeHead(404); return res.end('Not found'); }
    const body = Buffer.from(b64, 'base64');
    res.writeHead(200, { 'Content-Type': MIME[path.extname(rel).toLowerCase()] || 'application/octet-stream', 'Content-Length': body.length, 'Cache-Control': 'no-cache' });
    return res.end(req.method === 'HEAD' ? undefined : body);
  }
  const abs = path.normalize(path.join(PUBLIC, rel));
  if (!abs.startsWith(PUBLIC + path.sep)) { res.writeHead(403); return res.end(); }
  serveFile(req, res, abs, MIME[path.extname(abs).toLowerCase()] || 'application/octet-stream', { 'Cache-Control': 'no-cache' });
});

server.on('upgrade', handleUpgrade);
server.requestTimeout = 0;      // large uploads on slow connections
server.headersTimeout = 30000;
server.keepAliveTimeout = 15000;

setInterval(() => {
  const now = Date.now();
  for (const [code, s] of sessions) {
    if (s.clients.size === 0 && now - s.touched > SESSION_TTL) { removeFile(s); sessions.delete(code); }
  }
  for (const [ip, list] of createLog) if (!list.some((t) => now - t < 3600000)) createLog.delete(ip);
}, 10 * 60 * 1000).unref();

if (require.main === module) {
  server.listen(PORT, '0.0.0.0', () => {
    console.log('\nMulticonnect is running.\n');
    console.log('  On this computer:   http://localhost:' + PORT);
    lanAddresses().forEach((a) => console.log('  For students (same Wi-Fi): ' + a));
    console.log('\nOpen the first address, press "Start a class", then share the code or QR code.\n');
  });
}
module.exports = server;
